import{_ as d,D as r,c as l,j as t,a as e,I as s,a4 as a,o as n}from"./chunks/framework.CRCV4hx_.js";const w=JSON.parse('{"title":"Languages","description":"","frontmatter":{},"headers":[],"relativePath":"languages.md","filePath":"languages.md"}'),i={name:"languages.md"},c=a('<h1 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h1><p>Most of the texts in Resrv are read from the addon&#39;s language file. This page explains how to change them or add new translations.</p><h2 id="publishing-the-language-file" tabindex="-1">Publishing the language file <a class="header-anchor" href="#publishing-the-language-file" aria-label="Permalink to &quot;Publishing the language file&quot;">​</a></h2><p>If you didn&#39;t publish them during installation, you first need to publish the language files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=resrv-language</span></span></code></pre></div><p>You should now see the language file in <code>lang/vendor/statamic-resrv/en/frontend.php</code>.</p><p>You can edit this file in order the change the wording used in most areas of Resrv&#39;s frontend.</p><h2 id="adding-new-translations" tabindex="-1">Adding new translations <a class="header-anchor" href="#adding-new-translations" aria-label="Permalink to &quot;Adding new translations&quot;">​</a></h2><p>When using multisite, you can simply create a new folder with the handle of your other sites in <code>lang/vendor/statamic-resrv/</code>. Then, simply copy frontend.php to the new folder and translate the strings.</p>',9),h={id:"updated-keys-in-v6",tabindex:"-1"},p=t("a",{class:"header-anchor",href:"#updated-keys-in-v6","aria-label":'Permalink to "Updated keys in v6 <Badge type="tip" text="NEW" />"'},"​",-1),u=a('<div class="warning custom-block"><p class="custom-block-title">RE-PUBLISH OR MERGE</p><p>v6 changes the wording of several keys and adds new ones. If you already translated <code>frontend.php</code> in v5, the new keys won&#39;t exist in your published copy. Re-publish the file (and re-apply your translations) or merge the new keys into your existing file.</p></div><h3 id="property-keys-now-read-rate" tabindex="-1">&quot;Property&quot; keys now read &quot;Rate&quot; <a class="header-anchor" href="#property-keys-now-read-rate" aria-label="Permalink to &quot;&quot;Property&quot; keys now read &quot;Rate&quot;&quot;">​</a></h3><p>The v5 &quot;advanced availability&quot; feature has been replaced by the collection-scoped <a href="./rates">Rates</a> system. The existing <code>property</code>-themed keys were kept for backward compatibility, but their English values now read &quot;rate&quot;:</p><table tabindex="0"><thead><tr><th>Key</th><th>v5 value</th><th>v6 value</th></tr></thead><tbody><tr><td><code>selectProperty</code></td><td>Select property</td><td>Select rate</td></tr><tr><td><code>property</code></td><td>Property</td><td>Rate</td></tr><tr><td><code>multipleAvailable</code></td><td>Multiple properties available.</td><td>Multiple rates available.</td></tr><tr><td><code>pleaseSelectProperty</code></td><td>Please select a property…</td><td>Please select a rate from the search form to check prices and continue.</td></tr><tr><td><code>pleaseSelectPropertyToBook</code></td><td>Please select a property to book</td><td>Please select a rate to book</td></tr></tbody></table><p>Because the old keys still exist, a v5 translation file keeps working, but the rate selector now reads the new <code>selectRate</code> key (and the cart results read <code>pleaseSelectRateToBook</code>), so update the new keys below to translate the rate UI.</p><h3 id="new-rate-keys" tabindex="-1">New rate keys <a class="header-anchor" href="#new-rate-keys" aria-label="Permalink to &quot;New rate keys&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default value</th></tr></thead><tbody><tr><td><code>selectRate</code></td><td>Select rate</td></tr><tr><td><code>multipleRatesAvailable</code></td><td>Multiple rates available.</td></tr><tr><td><code>pleaseSelectRate</code></td><td>Please select a rate from the search form to check prices and continue.</td></tr><tr><td><code>pleaseSelectRateToBook</code></td><td>Please select a rate to book</td></tr></tbody></table><h3 id="cancellation-policy-keys" tabindex="-1">Cancellation policy keys <a class="header-anchor" href="#cancellation-policy-keys" aria-label="Permalink to &quot;Cancellation policy keys&quot;">​</a></h3><p>Used by the <a href="./rates#cancellation-policy">cancellation policy</a> label rendered on availability results, the checkout sidebar, reservation details and the confirmation email.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default value</th></tr></thead><tbody><tr><td><code>cancellationPolicy</code></td><td>Cancellation policy</td></tr><tr><td><code>nonRefundable</code></td><td>Non-refundable</td></tr><tr><td><code>freeCancellationUntilDate</code></td><td>Free cancellation until :date</td></tr></tbody></table><p>The <code>:date</code> placeholder is replaced with the resolved free-cancellation date.</p><h3 id="cart-keys" tabindex="-1">Cart keys <a class="header-anchor" href="#cart-keys" aria-label="Permalink to &quot;Cart keys&quot;">​</a></h3><p>Used by the <a href="./cart-booking">cart booking</a> flow when booking multiple items in one go.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default value</th></tr></thead><tbody><tr><td><code>addToBooking</code></td><td>Add to booking</td></tr><tr><td><code>yourBooking</code></td><td>Your booking</td></tr><tr><td><code>clear</code></td><td>Clear</td></tr></tbody></table>',14);function y(b,g,k,f,m,v){const o=r("Badge");return n(),l("div",null,[c,t("h2",h,[e("Updated keys in v6 "),s(o,{type:"tip",text:"NEW"}),e(),p]),u])}const P=d(i,[["render",y]]);export{w as __pageData,P as default};
